<?php
namespace App\Http\Controllers;
use Illuminate\Routing\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use App\Services\{Support,Municipalities,Dispatch};
class TransferController extends Controller {
 private function center(){abort_unless(auth()->user()->role==='sorting_center',403);$c=DB::table('sorting_centers')->where('user_id',auth()->id())->first();abort_unless($c,403);return $c;}
 public function index(){ $c=$this->center();return view('transfers',['links'=>app(CommonController::class)->links(),'parcels'=>DB::table('parcels as p')->join('orders as o','o.id','=','p.order_id')->where('p.center_id',$c->id)->whereIn('p.status',['AT_SORTING_CENTER','SORTED','TRANSFER_OFFERED'])->select('p.*','o.address_snapshot','o.address_id')->get(),'incoming'=>DB::table('parcels')->where('destination_center_id',$c->id)->where('status','IN_TRANSIT_CENTER')->get(),'drivers'=>DB::table('users')->where('company_id',auth()->id())->where('role','rider')->where('courier_type','driver')->where('active',1)->where('account_status','active')->where('approval_status','approved')->where('online',1)->get()]);}
 public function offer(Request $r,int $id){$c=$this->center();$v=$r->validate(['rider_id'=>'required|integer']);DB::transaction(function()use($id,$c,$v){$p=DB::table('parcels')->where('id',$id)->where('center_id',$c->id)->lockForUpdate()->first();abort_unless($p,404);if(!in_array($p->status,['AT_SORTING_CENTER','SORTED','TRANSFER_OFFERED']))Support::fail('parcel','Receive the parcel before transferring it.');$o=DB::table('orders')->find($p->order_id);$a=$o->address_snapshot?json_decode($o->address_snapshot):DB::table('addresses')->find($o->address_id);$destination=Municipalities::centerFor($a);if(!$destination||$destination->id===$c->id)Support::fail('destination','No different approved sorting center serves the buyer municipality.');
 $u=DB::table('users')->where('id',$v['rider_id'])->where('company_id',auth()->id())->lockForUpdate()->first();abort_unless($u,403);Municipalities::courier($u,$p,'transfer');if(!$u->online||!$u->last_seen_at||now()->diffInMinutes($u->last_seen_at,true)>=30)Support::fail('rider_id','Driver must be Online.');if(DB::table('assignments')->where('rider_id',$u->id)->whereIn('status',['accepted','offered'])->count()>=3)Support::fail('rider_id','Driver is at capacity.');if(DB::table('assignments')->where('parcel_id',$id)->where('kind','transfer')->where('status','accepted')->exists())Support::fail('parcel','A driver already accepted this transfer.');
 DB::table('assignments')->where('parcel_id',$id)->where('kind','transfer')->where('status','offered')->update(['status'=>'reassigned','updated_at'=>now()]);
 DB::table('assignments')->insert(['parcel_id'=>$id,'rider_id'=>$u->id,'kind'=>'transfer','status'=>'offered','expires_at'=>now()->addMinutes(5),'earnings'=>50,'created_at'=>now(),'updated_at'=>now()]);DB::table('parcels')->where('id',$id)->update(['destination_center_id'=>$destination->id,'status'=>'TRANSFER_OFFERED','updated_at'=>now()]);DB::table('orders')->where('id',$p->order_id)->update(['status'=>'TRANSFER_OFFERED','updated_at'=>now()]);$this->history($p,'TRANSFER_OFFERED','Transfer to '.$destination->name);Support::notify([$u->id,$destination->user_id],"Center transfer offered for {$p->tracking_code} to {$destination->name}.");});return back()->with('success','Transfer offered to driver.');}
 public function depart(int $id){abort_unless(auth()->user()->role==='rider'&&auth()->user()->courier_type==='driver',403);DB::transaction(function()use($id){$p=DB::table('parcels')->where('id',$id)->lockForUpdate()->first();abort_unless($p&&$p->status==='TRANSFER_OFFERED'&&$p->destination_center_id,422);$a=DB::table('assignments')->where('parcel_id',$id)->where('kind','transfer')->where('rider_id',auth()->id())->where('status','accepted')->lockForUpdate()->first();abort_unless($a,403);Municipalities::courier(auth()->user(),$p,'transfer');DB::table('parcels')->where('id',$id)->update(['status'=>'IN_TRANSIT_CENTER','updated_at'=>now()]);DB::table('orders')->where('id',$p->order_id)->update(['status'=>'IN_TRANSIT_CENTER','updated_at'=>now()]);$this->history($p,'IN_TRANSIT_CENTER','Driver departed source sorting center.');});return request()->expectsJson()?response()->json(['message'=>'Transfer departed.']):back()->with('success','Transfer departed. Destination center must confirm receipt.');}
 public function receive(int $id){$c=$this->center();DB::transaction(function()use($id,$c){$p=DB::table('parcels')->where('id',$id)->where('destination_center_id',$c->id)->lockForUpdate()->first();abort_unless($p&&$p->status==='IN_TRANSIT_CENTER',422);DB::table('assignments')->where('parcel_id',$id)->where('kind','transfer')->where('status','accepted')->update(['status'=>'completed','updated_at'=>now()]);DB::table('parcels')->where('id',$id)->update(['center_id'=>$c->id,'destination_center_id'=>null,'delivery_area_id'=>null,'status'=>'AT_SORTING_CENTER','updated_at'=>now()]);DB::table('orders')->where('id',$p->order_id)->update(['status'=>'AT_SORTING_CENTER','updated_at'=>now()]);$this->history($p,'AT_SORTING_CENTER','Destination sorting center confirmed receipt.');Support::notify([$c->user_id],"Parcel {$p->tracking_code} received; sort for local delivery.");});return back()->with('success','Transfer received. Sort and assign a local delivery rider.');}
 private function history($p,string $status,string $reason){DB::table('status_history')->insert(['parcel_id'=>$p->id,'from_status'=>$p->status,'to_status'=>$status,'actor_id'=>auth()->id(),'reason'=>$reason,'created_at'=>now(),'updated_at'=>now()]);Support::audit('center-transfer','parcel',$p->id,$p,['status'=>$status],$reason);}
}
